import { AssetLoader } from './AssetLoader';

export type AssetFrame = {
    x: number;
    y: number;
    w: number;
    h: number;
};

export type AssetEntry = {
    alias: string;
    spritePath: string;
    jsonPath?: string;
    frames?: Record<string, AssetFrame>;
};

export const GAME_ASSET_MANIFEST: AssetEntry[] = [
    {
        alias: 'symbols-sheet',
        spritePath: `${import.meta.env.BASE_URL}graphics/symbols.png`,
        jsonPath: `${import.meta.env.BASE_URL}graphics/symbols.json`,
    },
    {
        alias: 'game-backgrounds',
        spritePath: `${import.meta.env.BASE_URL}graphics/background.jpg`,
        frames: {
            summer: { x: 35, y: 202, w: 954, h: 306 },
            snow: { x: 35, y: 520, w: 954, h: 286 },
        },
    },
];

export class AssetManifest {
    public static async loadAssets(onProgress?: (progress: number) => void): Promise<void> {
        onProgress?.(0);

        for (let i = 0; i < GAME_ASSET_MANIFEST.length; i += 1) {
            const asset = GAME_ASSET_MANIFEST[i];

            try {
                await AssetLoader.load(
                    asset.alias,
                    asset.spritePath,
                    asset.jsonPath,
                    asset.frames
                );
            } catch (error) {
                console.warn(`[AssetManifest] Failed to load "${asset.alias}".`, error);
            }

            onProgress?.((i + 1) / GAME_ASSET_MANIFEST.length);
        }
    }
}
