import * as PIXI from 'pixi.js';

type SpriteSheetData = {
    textures?: Record<string, PIXI.Texture>;
    frames?: Record<string, {
        frame: {
            x: number;
            y: number;
            w: number;
            h: number;
        };
    }>;
};

type AssetFrame = {
    x: number;
    y: number;
    w: number;
    h: number;
};

export class AssetLoader {
    private static readonly TEXTURES = new Map<string, PIXI.Texture>();

    private static getTextureKey(alias: string, frameName: string): string {
        return `${alias}:${frameName}`;
    }

    public static async load(
        alias: string,
        spritePath: string,
        jsonPath?: string,
        frames?: Record<string, AssetFrame>
    ): Promise<PIXI.Texture> {
        const texture = await PIXI.Assets.load(spritePath) as PIXI.Texture;

        if (jsonPath) {
            const atlas = await PIXI.Assets.load(jsonPath) as SpriteSheetData;
            let registeredFrames = 0;

            if (atlas.textures) {
                for (const [frameName, frameTexture] of Object.entries(atlas.textures)) {
                    this.TEXTURES.set(this.getTextureKey(alias, frameName), frameTexture);
                    registeredFrames += 1;
                }
            } else {
                for (const [frameName, frameData] of Object.entries(atlas.frames ?? {})) {
                    const frame = frameData.frame;
                    this.TEXTURES.set(this.getTextureKey(alias, frameName), new PIXI.Texture({
                        source: texture.source,
                        frame: new PIXI.Rectangle(frame.x, frame.y, frame.w, frame.h),
                        orig: new PIXI.Rectangle(frame.x, frame.y, frame.w, frame.h),
                        label: `${alias}:${frameName}`,
                    }));
                    registeredFrames += 1;
                }
            }

            if (registeredFrames === 0) {
                throw new Error(`No frames were found in sprite atlas: ${jsonPath}`);
            }
        }

        for (const [frameName, frame] of Object.entries(frames ?? {})) {
            this.TEXTURES.set(this.getTextureKey(alias, frameName), new PIXI.Texture({
                source: texture.source,
                frame: new PIXI.Rectangle(frame.x, frame.y, frame.w, frame.h),
                orig: new PIXI.Rectangle(frame.x, frame.y, frame.w, frame.h),
                label: `${alias}:${frameName}`,
            }));
        }

        return texture;
    }

    public static getTexture(alias: string, frameName: string): PIXI.Texture {
        const loadedTexture = AssetLoader.TEXTURES.get(AssetLoader.getTextureKey(alias, frameName));
        if (loadedTexture) {
            return loadedTexture;
        }

        return PIXI.Texture.WHITE;
    }
}